package main

// Planning a parameter write-back (#718 slice 2): which files change, and
// to what, when the operator-tuned values the plant holds are put back in
// the repo as each tag's `init:`.
//
// An edit replaces the one scalar and nothing else: comments, layout and
// every other byte of the file stay as they were. A tag whose init cannot be
// edited that way (generated by a device profile, or not a literal number
// or boolean, or moved in the file since this controller started) is not
// written: it stays drift, reported with why.

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/joyautomation/nautilus/internal/project"
	"github.com/joyautomation/nautilus/lang/ir"
	"github.com/joyautomation/nautilus/runtime"
)

// paramUnwritable is a parameter the write-back leaves as drift.
type paramUnwritable struct {
	Name string
	Why  string
}

// paramPlan is the files a write-back changes.
type paramPlan struct {
	Files      []ioChange // path, was, exist, run (the new content)
	Written    map[string]any
	Unwritable []paramUnwritable
	Lines      []string // "SP: 65 -> 70", for the commit message
}

// readFn reads a project file by slash path.
type readFn func(path string) ([]byte, error)

func dirReader(dir string) (readFn, func(), error) {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, nil, err
	}
	return func(p string) ([]byte, error) { return root.ReadFile(filepath.FromSlash(p)) }, func() { root.Close() }, nil
}

func fsReader(base fs.FS) readFn {
	return func(p string) ([]byte, error) { return fs.ReadFile(base, p) }
}

// planParamWriteBack plans the edits for pend (the plant-ahead parameters).
// manifest is the manifest's project-relative path. Nothing is written.
func planParamWriteBack(read readFn, manifest string, pend []runtime.Parameter) (*paramPlan, error) {
	if len(pend) == 0 {
		return &paramPlan{}, nil
	}
	mraw, err := read(manifest)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", manifest, err)
	}
	m, err := project.ReadManifest(overlayRead{read: read, name: manifest, data: mraw}, manifest)
	if err != nil {
		return nil, err
	}
	// The files that can declare a tag, in the order composeTags reads them.
	paths := append(append([]string{}, m.TagFiles...), manifest)
	raws := map[string][]byte{manifest: mraw}
	docs := map[string]*yaml.Node{}
	seqs := map[string]*yaml.Node{}
	for i, p := range paths {
		p = filepath.ToSlash(filepath.Clean(p))
		paths[i] = p
		raw, ok := raws[p]
		if !ok {
			if raw, err = read(p); err != nil {
				return nil, fmt.Errorf("tag-files: %w", err)
			}
			raws[p] = raw
		}
		if err := oddBreaks(raw); err != nil {
			return nil, fmt.Errorf("%s: %w", p, err)
		}
		var doc yaml.Node
		if err := yaml.Unmarshal(raw, &doc); err != nil || len(doc.Content) == 0 {
			continue
		}
		docs[p] = &doc
		top := doc.Content[0]
		if p == manifest {
			if _, v := child(top, "tags"); v != nil {
				seqs[p] = v
			}
		} else {
			seqs[p] = top
		}
	}

	type edit struct {
		off, end int
		text     string
	}
	byFile := map[string][]edit{}
	plan := &paramPlan{Written: map[string]any{}}
	// The file's own spelling of a numeric init decides how to print the
	// new one (65.0 stays a real: 70 is written 70.0).
	for _, pr := range pend {
		unw := func(format string, a ...any) {
			plan.Unwritable = append(plan.Unwritable, paramUnwritable{pr.Name, fmt.Sprintf(format, a...)})
		}
		var vn *yaml.Node
		var in string
		for _, p := range paths {
			seq := seqs[p]
			if seq == nil || seq.Kind != yaml.SequenceNode {
				continue
			}
			for _, item := range seq.Content {
				if item.Kind != yaml.MappingNode {
					continue
				}
				if _, nv := child(item, "name"); nv != nil && ir.NameKey(nv.Value) == ir.NameKey(pr.Name) {
					_, vn = child(item, "init")
					in = p
					break
				}
			}
			if in != "" {
				break
			}
		}
		switch {
		case in == "":
			unw("its tag is not written in the manifest or a tag file (a device profile generates it): change the profile, or the value by hand")
			continue
		case vn == nil:
			unw("%s declares it with no init: to edit", in)
			continue
		case vn.Kind != yaml.ScalarNode || vn.Anchor != "" || vn.Style&(yaml.SingleQuotedStyle|yaml.DoubleQuotedStyle|yaml.LiteralStyle|yaml.FoldedStyle) != 0:
			unw("%s line %d: its init is not a plain number or boolean the edit can replace in place", in, vn.Line)
			continue
		}
		switch vn.ShortTag() {
		case "!!int", "!!float", "!!bool":
		default:
			unw("%s line %d: its init %q is not a number or boolean", in, vn.Line, vn.Value)
			continue
		}
		var cur any
		if err := vn.Decode(&cur); err != nil {
			unw("%s line %d: its init %q does not read as a value", in, vn.Line, vn.Value)
			continue
		}
		if runtime.ParamValuesEqual(cur, pr.Value) {
			// The repo already says it (a redeploy, or a hand edit): nothing
			// to write, and nothing left to carry.
			plan.Written[pr.Name] = pr.Value
			continue
		}
		// The file holds what this controller started with, or what its own
		// last commit put there; anything else moved without it.
		if !runtime.ParamValuesEqual(cur, pr.Init) && (pr.LastCommitted == nil || !runtime.ParamValuesEqual(cur, pr.LastCommitted)) {
			unw("%s line %d: the file's init is %s, not the %v this controller started with, so the repo moved since: bring it up to date, then redeploy", in, vn.Line, vn.Value, pr.Init)
			continue
		}
		text, ok := renderParamInit(vn.Value, pr.Value)
		if !ok {
			unw("its value %v cannot be written as an init", pr.Value)
			continue
		}
		off, ok := scalarOffset(raws[in], vn)
		if !ok {
			unw("%s line %d: could not place the edit", in, vn.Line)
			continue
		}
		byFile[in] = append(byFile[in], edit{off, off + len(vn.Value), text})
		plan.Written[pr.Name] = pr.Value
		plan.Lines = append(plan.Lines, fmt.Sprintf("%s: %s -> %s", pr.Name, vn.Value, text))
	}
	files := make([]string, 0, len(byFile))
	for p := range byFile {
		files = append(files, p)
	}
	sort.Strings(files)
	changed := map[string][]byte{}
	for _, p := range files {
		es := byFile[p]
		sort.Slice(es, func(i, j int) bool { return es[i].off > es[j].off })
		out := append([]byte(nil), raws[p]...)
		for _, e := range es {
			out = append(out[:e.off:e.off], append([]byte(e.text), out[e.end:]...)...)
		}
		changed[p] = out
		plan.Files = append(plan.Files, ioChange{path: p, was: raws[p], exist: true, run: string(out)})
	}
	if len(changed) > 0 {
		// The edited project must still load and say what was meant.
		got, err := project.ReadManifest(overlayRead{read: read, files: changed, name: manifest, data: nil}, manifest)
		if err != nil {
			return nil, fmt.Errorf("the edited files would not load, so nothing is written: %w", err)
		}
		inits := map[string]any{}
		for _, t := range got.Tags {
			inits[ir.NameKey(t.Name)] = t.Init
		}
		for name, v := range plan.Written {
			if !runtime.ParamValuesEqual(inits[ir.NameKey(name)], v) {
				return nil, fmt.Errorf("the edit of %s does not read back as %v (it reads %v), so nothing is written", name, v, inits[ir.NameKey(name)])
			}
		}
	}
	sort.Strings(plan.Lines)
	sort.Slice(plan.Unwritable, func(i, j int) bool { return plan.Unwritable[i].Name < plan.Unwritable[j].Name })
	return plan, nil
}

// renderParamInit spells a new init the way the old one was spelled: a real
// that was written 65.0 stays one.
func renderParamInit(old string, v any) (string, bool) {
	switch x := v.(type) {
	case bool:
		return strconv.FormatBool(x), true
	case int:
		return strconv.Itoa(x), true
	case int64:
		return strconv.FormatInt(x, 10), true
	case float64:
		if x != x || x > 1e300 || x < -1e300 {
			return "", false
		}
		s := strconv.FormatFloat(x, 'f', -1, 64)
		if x == float64(int64(x)) && strings.ContainsAny(old, ".eE") && !strings.Contains(s, ".") {
			s += ".0"
		}
		return s, true
	}
	return "", false
}

// scalarOffset is the byte offset of a scalar node's text in raw. YAML
// counts columns in characters; the text there must be the node's value.
func scalarOffset(raw []byte, n *yaml.Node) (int, bool) {
	off := 0
	for i := 1; i < n.Line; i++ {
		j := bytes.IndexByte(raw[off:], '\n')
		if j < 0 {
			return 0, false
		}
		off += j + 1
	}
	line := raw[off:]
	if j := bytes.IndexByte(line, '\n'); j >= 0 {
		line = line[:j]
	}
	col := 0
	for i := 0; col < n.Column-1; col++ {
		if i >= len(line) {
			return 0, false
		}
		_, size := decodeRune(line[i:])
		i += size
		off += size
	}
	if !bytes.HasPrefix(raw[off:], []byte(n.Value)) {
		return 0, false
	}
	return off, true
}

func decodeRune(b []byte) (rune, int) {
	r := []rune(string(b[:min(len(b), 4)]))
	if len(r) == 0 {
		return 0, 1
	}
	return r[0], len(string(r[0]))
}

// overlayRead is a read function as the fs.FS ReadManifest wants, with files
// replaced.
type overlayRead struct {
	read  readFn
	files map[string][]byte
	name  string
	data  []byte
}

func (o overlayRead) Open(name string) (fs.File, error) {
	b, err := o.ReadFile(name)
	if err != nil {
		return nil, err
	}
	return &memFile{Reader: bytes.NewReader(b), name: path.Base(name), size: int64(len(b))}, nil
}

func (o overlayRead) ReadFile(name string) ([]byte, error) {
	if b, ok := o.files[name]; ok {
		return b, nil
	}
	if o.data != nil && name == o.name {
		return o.data, nil
	}
	b, err := o.read(name)
	if err != nil && errors.Is(err, os.ErrNotExist) {
		return nil, fs.ErrNotExist
	}
	return b, err
}
